def solve_8queens():
    # backtracking
    n = 8
    cols = [False]*n
    diag1 = [False]*(2*n-1)  # r+c
    diag2 = [False]*(2*n-1)  # r-c+n-1
    board = [0]*n

    def backtrack(r):
        if r == n:
            return True
        for c in range(n):
            if not cols[c] and not diag1[r+c] and not diag2[r-c+n-1]:
                board[r] = c
                cols[c] = diag1[r+c] = diag2[r-c+n-1] = True
                if backtrack(r+1):
                    return True
                cols[c] = diag1[r+c] = diag2[r-c+n-1] = False
        return False

    if backtrack(0):
        return board
    return None

sol = solve_8queens()
print(sol)

def verify(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j] or abs(board[i]-board[j]) == abs(i-j):
                return False
    return True

print(verify([0,4,7,5,2,6,1,3]))
